__define("./components/Overview.css", function (module) {
module.exports = "/* 总览页：只读统计，风格与其它视图一致（全用 --moshu-* / --dsw-alias-*）。 */\n\n.moshu-root.overview-page{\n  display:flex;flex-direction:column;gap:18px;\n  height:100%;min-height:0;overflow:auto;\n  padding:4px 2px 28px;color:var(--moshu-ink)}\n\n/* 统计 */\n.moshu-root .ov-stats{\n  display:grid;grid-template-columns:repeat(auto-fit,minmax(96px,1fr));gap:10px}\n.moshu-root .ov-stat{\n  display:flex;flex-direction:column;gap:2px;\n  padding:12px 14px;border-radius:11px;\n  border:1px solid var(--moshu-line);background:var(--moshu-surface)}\n.moshu-root .ov-stat span{font-size:11px;color:var(--moshu-muted)}\n.moshu-root .ov-stat strong{font-size:19px;font-weight:600;letter-spacing:-.01em}\n\n/* 进度 */\n.moshu-root .ov-progress{\n  padding:14px 16px;border-radius:11px;\n  border:1px solid var(--moshu-line);background:var(--moshu-surface)}\n.moshu-root .ov-progress-head{\n  display:flex;align-items:baseline;justify-content:space-between;\n  font-size:12px;color:var(--moshu-muted);margin-bottom:8px}\n.moshu-root .ov-progress-head b{font-size:14px;color:var(--moshu-ink)}\n.moshu-root .ov-progress-track{\n  height:6px;border-radius:999px;overflow:hidden;\n  background:color-mix(in oklab,var(--dsw-alias-label-primary) 12%,transparent)}\n.moshu-root .ov-progress-track i{\n  display:block;height:100%;border-radius:999px;\n  background:var(--dsw-alias-state-business-primary)}\n.moshu-root .ov-progress p{margin:8px 0 0;font-size:11px;color:var(--moshu-faint)}\n\n/* 区块 */\n.moshu-root .ov-block{display:flex;flex-direction:column;gap:8px}\n.moshu-root .ov-block-head{display:flex;align-items:center;gap:7px;color:var(--moshu-muted)}\n.moshu-root .ov-block-head h2{margin:0;font-size:12.5px;font-weight:600;color:var(--moshu-ink)}\n.moshu-root .ov-empty{margin:0;font-size:11.5px;color:var(--moshu-faint)}\n\n/* 章节表 */\n.moshu-root .ov-chapters{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:2px}\n.moshu-root .ov-chapter{\n  width:100%;display:grid;grid-template-columns:34px minmax(0,1fr) auto auto;align-items:center;gap:10px;\n  padding:8px 10px;border:0;border-radius:8px;background:transparent;\n  color:inherit;text-align:left;cursor:pointer;font:inherit}\n.moshu-root .ov-chapter:hover{background:var(--moshu-hover)}\n.moshu-root .ov-chapter-no{font-family:var(--moshu-mono);font-size:10.5px;color:var(--moshu-faint)}\n.moshu-root .ov-chapter-title{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12.5px}\n.moshu-root .ov-chapter-words{font-family:var(--moshu-mono);font-size:10.5px;color:var(--moshu-muted)}\n.moshu-root .ov-chapter-status{\n  font-size:10px;padding:2px 7px;border-radius:999px;\n  border:1px solid var(--moshu-line);color:var(--moshu-muted)}\n.moshu-root .ov-chapter-status.is-已完成{\n  color:var(--dsw-alias-state-success-primary);\n  border-color:color-mix(in oklab,var(--dsw-alias-state-success-primary) 40%,transparent)}\n.moshu-root .ov-chapter-status.is-草稿{\n  color:var(--dsw-alias-state-business-primary);\n  border-color:color-mix(in oklab,var(--dsw-alias-state-business-primary) 40%,transparent)}\n\n/* 最近改动 */\n.moshu-root .ov-recent{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:2px}\n.moshu-root .ov-recent button{\n  width:100%;display:flex;align-items:baseline;gap:10px;\n  padding:7px 10px;border:0;border-radius:8px;background:transparent;\n  color:inherit;text-align:left;cursor:pointer;font:inherit}\n.moshu-root .ov-recent button:hover{background:var(--moshu-hover)}\n.moshu-root .ov-recent-title{font-size:12px}\n.moshu-root .ov-recent-path{\n  margin-left:auto;font-size:10.5px;color:var(--moshu-faint);\n  overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n\n@media (max-width: 720px){\n  .moshu-root .ov-chapter{grid-template-columns:28px minmax(0,1fr) auto}\n  .moshu-root .ov-chapter-words{display:none}\n}\n";
});

