__define("./shell/workbench-overlay.css", function (module) {
module.exports = "/* 工作台全屏浮层：盖住整帧，用满窗口高度。颜色只用宿主 token。 */\n\n.moshu-overlay {\n  position: fixed;\n  inset: 0;\n  z-index: 2000; /* 盖住宿主自己的弹层（宿主最高 1100） */\n  display: flex;\n  flex-direction: column;\n  min-height: 0;\n  background: var(--dsw-alias-bg-base);\n  color: var(--dsw-alias-label-primary);\n}\n\n.moshu-overlay-bar {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  flex-shrink: 0;\n  padding: 4px 12px;\n  border-bottom: 1px solid var(--dsw-alias-border-l1);\n  background: var(--dsw-alias-bg-layer-1);\n}\n\n.moshu-overlay-mark {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  width: 24px;\n  height: 24px;\n  border-radius: 8px;\n  background: color-mix(in oklab, var(--dsw-alias-brand-primary) 12%, transparent);\n  color: var(--dsw-alias-brand-primary);\n}\n\n.moshu-overlay-title {\n  font-size: 13px;\n  font-weight: 600;\n  white-space: nowrap;\n}\n\n.moshu-overlay-hint {\n  margin-left: 4px;\n  color: var(--dsw-alias-label-tertiary);\n  font-size: 11.5px;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.moshu-overlay-close {\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n  margin-left: auto;\n  padding: 5px 12px;\n  border-radius: 999px;\n  border: 1px solid var(--dsw-alias-border-l2);\n  background: var(--dsw-alias-bg-layer-2);\n  color: var(--dsw-alias-label-secondary);\n  font-size: 12px;\n  cursor: pointer;\n  white-space: nowrap;\n  transition: background 0.15s, color 0.15s, border-color 0.15s;\n}\n\n.moshu-overlay-close:hover {\n  color: var(--dsw-alias-label-primary);\n  border-color: var(--dsw-alias-brand-primary);\n  background: color-mix(in oklab, var(--dsw-alias-brand-primary) 10%, var(--dsw-alias-bg-layer-2));\n}\n\n.moshu-overlay-close:focus-visible {\n  outline: 2px solid var(--dsw-alias-brand-primary);\n  outline-offset: 2px;\n}\n\n.moshu-overlay-body {\n  flex: 1;\n  min-height: 0;\n  overflow: hidden;\n}\n\n@media (max-width: 760px) {\n  .moshu-overlay-hint {\n    display: none;\n  }\n}\n\n\n/* 浮层里不要额外留白：上下都给内容。 */\n.moshu-overlay-head{padding:4px 12px;min-height:0}\n.moshu-overlay-body{min-height:0}\n\n\n/* 全屏条只做\"退出\"这一件事，压到最薄，把高度留给内容。 */\n.moshu-overlay-bar{padding:4px 12px;gap:8px;font-size:11.5px}\n.moshu-overlay-bar button{padding:3px 8px}\n";
});

__define("./shell/workbench-slot.css", function (module) {
module.exports = "/* 主区面板在工作台全屏时的提示卡。 */\n\n.moshu-slot-away {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: 8px;\n  height: 100%;\n  min-height: 240px;\n  padding: 32px;\n  text-align: center;\n  color: var(--dsw-alias-label-secondary);\n  background: var(--dsw-alias-bg-base);\n}\n\n.moshu-slot-away strong {\n  color: var(--dsw-alias-label-primary);\n  font-size: 14px;\n}\n\n.moshu-slot-away p {\n  margin: 0 0 8px;\n  max-width: 340px;\n  font-size: 12.5px;\n  line-height: 1.7;\n  color: var(--dsw-alias-label-tertiary);\n}\n\n.moshu-slot-away-btn {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  padding: 6px 14px;\n  border-radius: 999px;\n  border: 1px solid var(--dsw-alias-border-l2);\n  background: var(--dsw-alias-bg-layer-2);\n  color: var(--dsw-alias-label-secondary);\n  font-size: 12.5px;\n  cursor: pointer;\n}\n\n.moshu-slot-away-btn:hover {\n  color: var(--dsw-alias-label-primary);\n  border-color: var(--dsw-alias-brand-primary);\n}\n";
});

